mapper.select:
SELECT p.id, p.category_id, c.name AS category_name, p.name, p.subtitle, p.main_image, p.price, CASE WHEN p.stock > 0 THEN 'IN_STOCK' ELSE 'OUT_OF_STOCK' END AS stock_status, p.sales, p.status FROM product p LEFT JOIN category c ON c.id = p.category_id AND c.deleted = 0 WHERE p.deleted = 0 AND p.status = 'ON_SALE' AND p.audit_status = 'APPROVED'
AND p.category_id = #{query.categoryId}
AND (p.name LIKE CONCAT('%', #{query.keyword}, '%') OR p.subtitle LIKE CONCAT('%', #{query.keyword}, '%'))
AND p.price >= #{query.minPrice}
AND p.price <= #{query.maxPrice}
ORDER BY ${query.sortColumn} ${query.sortDirection}, p.id DESC

SELECT p.id, p.category_id, c.name AS category_name, COALESCE(mp.store_name, u.nickname, u.username, '') AS merchant_name, p.name, p.main_image, p.price, p.stock, p.sales, p.status, p.audit_status, p.audit_reason, p.audit_by, p.audit_time, p.sort, p.created_at, p.updated_at FROM product p LEFT JOIN category c ON c.id = p.category_id AND c.deleted = 0 LEFT JOIN user u ON u.id = p.merchant_id AND u.deleted = 0 LEFT JOIN merchant_profile mp ON mp.user_id = p.merchant_id WHERE p.deleted = 0
AND p.merchant_id = #{query.merchantId}
AND p.category_id = #{query.categoryId}
AND p.name LIKE CONCAT('%', #{query.keyword}, '%')
AND p.status = #{query.status}
AND p.audit_status = #{query.auditStatus}
ORDER BY ${query.sortColumn} ${query.sortDirection}, p.id DESC
